<x-admin-layout title="Pengguna"><h1>Pengguna</h1><p class="muted">Cari akun dan kelola ketersediaannya dengan alasan yang tercatat.</p><form class="filter-row"><x-field name="q" label="Nama atau email" :value="request('q')"/><div class="field"><label for="role">Role</label><select id="role" name="role"><option value="">Semua role</option>@foreach(['volunteer','organizer','admin'] as $role)<option @selected(request('role')===$role)>{{ $role }}</option>@endforeach</select></div><div class="field"><label for="active">Status akun</label><select id="active" name="active"><option value="">Semua status</option><option value="1" @selected(request('active')==='1')>Aktif</option><option value="0" @selected(request('active')==='0')>Nonaktif</option></select></div><button class="btn">Cari</button></form><div class="card table-wrap"><table><thead><tr><th>Pengguna</th><th>Role</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>@forelse($users as $u)<tr><td>{{ $u->name }}<br><span class="hint">{{ $u->email }}</span></td><td>{{ $u->role }}</td><td>{{ $u->active?'Aktif':'Nonaktif' }}</td><td>@if($u->role!=='admin')<details><summary>{{ $u->active?'Nonaktifkan':'Aktifkan' }} akun</summary><form method="post" action="{{ route('admin.toggle',$u) }}" data-confirm="Ubah status akun ini?">@csrf<label>Alasan perubahan<input name="reason" required maxlength="500"></label><button class="btn secondary">Simpan Status</button></form></details>@else<span class="hint">Akun pengelola</span>@endif</td></tr>@empty<tr><td colspan="4">Tidak ada akun sesuai filter.</td></tr>@endforelse</tbody></table></div>{{ $users->links() }}</x-admin-layout>